    func userNotificationCenter(_ center: UNUserNotificationCenter, openSettingsFor notification: UNNotification?) {
      call("userNotificationCenterOpenSettingsForNotification") { b in [b.encode(object: center), b.encode(optional: notification) { b.encode(object: $0) }] }
    }
  }
}
